"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["29773"],{6486(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_eliminacao.area_invalida","status":422,"titulo":"A \xe1rea do corte n\xe3o \xe9 um c\xf3digo de \xe1rea do ENEM bem formado"},"descricao":{"codigo":"uniplus.selecao.regra_eliminacao.area_invalida","requisitos":[],"oQueAconteceu":["Uma regra de elimina\xe7\xe3o `ELIMINACAO_CORTE_EM_AREA` informou, em `areaCodigo`, um c\xf3digo\\nde \xe1rea que n\xe3o tem a forma exigida. Esse c\xf3digo identifica a \xe1rea do ENEM em que\\no candidato precisa atingir o m\xednimo, e deve ter at\xe9 30 caracteres, formados s\xf3\\npor letras mai\xfasculas sem acento, algarismos e sublinhado. Um c\xf3digo em branco\\ntamb\xe9m \xe9 recusado.","Esta confer\xeancia olha s\xf3 a forma do c\xf3digo. Se a classifica\xe7\xe3o usa o quadro de\\npesos por \xe1rea, a \xe1rea do corte ainda precisa existir nesse quadro, e essa\\nconfer\xeancia \xe9 outra, com recusa pr\xf3pria. A primeira regra com problema\\ninterrompe a confer\xeancia, sem acumular com as demais. Nada foi gravado."],"comoResolver":["Corrija o `areaCodigo` da regra para um c\xf3digo de \xe1rea bem formado, em letras mai\xfasculas, sem acento e sem espa\xe7os. Quando a classifica\xe7\xe3o j\xe1 tem quadro de pesos por \xe1rea, escreva o c\xf3digo exatamente como o quadro o define."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo (`PUT /api/selecao/processos-seletivos/{id}/classificacao`)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra eliminacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);